MultiLanguageSpellData['en'][354349] = {name = "Pounced", additional_info = "60 yd range\nInstant\n[q]Mawrat sacrifices itself to stun and damage the enemy."}
MultiLanguageSpellData['en'][354351] = {name = "Sanctum Gloomcharger", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Only the Jailer's most powerful lieutenants are gifted these steeds to stalk the halls of the Tower.\"\nDrop:\nThe Nine\nZone:\nSanctum of Domination"}
MultiLanguageSpellData['en'][354352] = {name = "Soulbound Gloomcharger", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Ve'nari has many methods of sneaking around the Maw and disrupting the Jailer's plans, including binding his own minions.\"\nDrop:\nMysterious Gift from Ve'nari\nZone:\nThe Maw"}
MultiLanguageSpellData['en'][354353] = {name = "Fallen Charger", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The charger's screams echo across the Maw as it continues a never-ending ride across the land, forever looking for escape from the endless torments it has been forced to endure.\"\nDrop:\nZone:\nThe Maw"}
MultiLanguageSpellData['en'][354354] = {name = "Hand of Nilganihmaht", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Of all the giants who dared defy the Jailer, Nilganihmaht was the most arrogant. For this transgression, the giant's severed hand was hidden within a veil of torments, and the rings that could summon it back were scattered across the Maw.\"\nZone:\nThe Maw"}
MultiLanguageSpellData['en'][354355] = {name = "Hand of Salaranga", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Salaranga was the most cunning of her kin and hid amongst the Beastwarrens. She struck at the Banished One with a horde of bestial allies. It did not matter.\"\nAchievement:\nBreaking the Chains\nZone:\nKorthia and The Maw"}
MultiLanguageSpellData['en'][354356] = {name = "Amber Shardhide", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The bright colors of Korthian wildlife indicate that they have either few predators, or are tough enough to fight back.\"\nVendor:\nDuchess Mynx\nZone:\nKorthia\nDeath's Advance - Revered\nCost:\n5000"}
MultiLanguageSpellData['en'][354357] = {name = "Crimson Shardhide", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"When Korthia was pulled into The Maw, only a few hardy species survived.\"\nDrop:\nMalbog\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354358] = {name = "Darkmaul", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"An older shardhide, Darkmaul was relatively tame and friendly around Korthians. He was thought lost to the calamity.\"\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354359] = {name = "Fierce Razorwing", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Razorwings generally stay away from other Korthian species, but with time and patience, they can be tamed as well.\"\nDrop:\nDeath's Advance Supplies\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354360] = {name = "Garnet Razorwing", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Korthia was once known for its bright red flowers. Several species were known for consuming or rolling in them, and taking on bright red coloration as a result.\"\nDrop:\nReliwik the Defiant\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354361] = {name = "Dusklight Razorwing", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Razorwings can be seen throughout Korthia, making their nests on high hills and in trees.\"\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354362] = {name = "Wandering Arden Doe", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"A curious and inquisitive doe, she doesn't mean to worry her master, she just gets distracted easily. Especially with all of the new things to see on Korthia.\"\nZone:\nKorthia"}
MultiLanguageSpellData['en'][354363] = {name = "Grim Portent", additional_info = "Instant\n[q]Fatescribe Roh-Kalo binds several players to runes upon the Loom of Fates.\n\n After 9 sec, if a bound player is touching their assigned rune, the Fatescribe inflicts 19968 Shadow damage to all players within the rune.\n\n If a rune expires without its bound player inside, the Fatescribe inflicts 107829 Shadow damage to all players."}
