MultiLanguageSpellData['en'][354374] = {name = "Banshee's Bane", additional_info = "Unlimited range\nInstant\n[q]Sylvanas burdens targets with a ravenous affliction, inflicting 1 Shadow damage every second. This effect stacks. Upon removal, this coalesces into a pool of shadow on the ground. Any player touching the pool gains Banshee's Bane , consuming the pool."}
