MultiLanguageSpellData['en'][359229] = {name = "Heartlight Vombata", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The Enlightened revere all creations of the First Ones, yet for many, the vombata of Zereth Mortis are the most beloved. These creatures are equal parts trusted beast of burden and beloved companion.\"\nVendor:\nVilo\nZone:\nZereth Mortis\nThe Enlightened - Exalted\nCost:\n5000"}
MultiLanguageSpellData['en'][359230] = {name = "Curious Crystalsniffer", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Most vombata enjoy tunneling through the ground, but these sniffers seem to have an unerring ability to locate crystals buried deep underground and will congregate around large deposits.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359231] = {name = "Darkened Vombata", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The schematic to synthesize these darkened vombata seem to have appeared as a reaction to the Mawsworn invasion. The resulting vombata look different--darker, much like the invaders--but behave normally.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359232] = {name = "Adorned Vombata", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Red-colored vombata are considered lucky by the Enlightened. It was a red vombata that was present when they first arrived in Zereth Mortis.\"\nProfession:\nProtoform Synthesis"}
