MultiLanguageSpellData['en'][359317] = {name = "Wen Lo, the River's Edge", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The rivers of Pandaria, like Wen Lo, are unpredictable in nature. They may remain calm, bringing water to the crops, or flood, bringing ruin. Wen Lo reminds us that we must adapt to the challenges of life.\"\nIn-Game Shop"}
MultiLanguageSpellData['en'][359318] = {name = "Soaring Spelltome", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"In the forgotten depths of the Dalaran library, this oversized tome was found flapping madly around the room. Open the pages of this arcane-infused book and hitch a ride to magical adventure.\"\nAchievement:\nA Tour of Towers\nCategory:\nTimewalking"}
