MultiLanguageSpellData['en'][359364] = {name = "Bronzewing Vespoid", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Bronzewing vespoids are the result of attempting to synthesize a vespoid queen with no other members of a new hive. While no mortal has yet discovered how to synthesize a hive, the bronzewings are reliable mounts just as they are.\"\nProfession:\nProtoform Synthesis"}
