MultiLanguageSpellData['en'][359367] = {name = "Forged Spiteflyer", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"There's nothing that can make you feel as alive quite like riding through the realm of Death while atop a being that hates you.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359372] = {name = "Mawdapted Raptora", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Since the Jailer's incursion, new raptora have been synthesized by Zereth Mortis that are capable of resisting the corrupting influence of the Maw.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359373] = {name = "Raptora Swooper", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The raptora swooper is one of the most vicious iterations of its kind, perfectly suited for its ecological niche. Needing no further adjustments, the ones synthesized today are identical to those created in the past.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359374] = {name = "Negation Ward", additional_info = "30 yd range\n1.5 sec cast\n[q]Shields the target, causing Cosmic damage to attackers for 10 sec.\n(250ms cooldown)"}
MultiLanguageSpellData['en'][359375] = {name = "Negation Ward", additional_info = "50 yd range\nInstant\n[q]Inflicts Cosmic damage."}
MultiLanguageSpellData['en'][359376] = {name = "Bronze Helicid", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Some helicids of Zereth Mortis have strangely metallic shells. The ones who do are generally a bronze color, indistinct from the metal any novice miner could work, save that this creature's construction far surpasses the skill of any novice.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359377] = {name = "Unsuccessful Prototype Fleetpod", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This creature was not designed by the First Ones, but instead by an unknown being attempting to create a very fast runner. Needless to say the attempt failed, because this mount is very slow.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359378] = {name = "Scarlet Helicid", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This helicid's unusual reddish tint is clearly intentional in its design, but the only other difference between these and other helicids is the unusual lack of any ooze.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359379] = {name = "Shimmering Aurelid", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Though it was once created to defend the Sepulcher of the First Ones, with its primary function now completed, it now obediently follows your command.\"\nAchievement:\nGlory of the Sepulcher Raider\nCategory:\nDungeons & Raids"}
MultiLanguageSpellData['en'][359380] = {name = "Depthstalker", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Poached from Zereth Mortis, a few of these jellyfish were lost when the poachers' ship sank. They found a new home in the Great Sea's depths.\"\nTrading Post"}
MultiLanguageSpellData['en'][359381] = {name = "Cryptic Aurelid", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The Cyphers of the First Ones are beyond any mortal understanding. A curious effect of the language is that, for reasons unknown, some aurelids are drawn to mortals who aspire to unlock its mystery.\"\nAchievement:\nFrom A to Zereth\nCategory:\nShadowlands"}
MultiLanguageSpellData['en'][359383] = {name = "Immediate Extermination", additional_info = nil}
MultiLanguageSpellData['en'][359384] = {name = "Bron's Call to Action", additional_info = "Instant\n[q]After using 75 damaging or healing spells and abilities, your next spell or ability summons Bron, who knocks enemies back on arrival and then attacks and heals your targets for 30 sec."}
MultiLanguageSpellData['en'][359386] = {name = "Mawsworn Barrier", additional_info = nil}
MultiLanguageSpellData['en'][359387] = {name = "Winds of Winter", additional_info = "Instant\n[q]While inside the Maw or Torghast, each time you deal a critical strike, the Winds accumulate 13% of that effect, up to a cap of 28572 per critical strike.\n\n Every 20 sec, the Winds unleash, dealing Frost damage equal to the total accumulation and and surrounding you in the Winds for 20 sec, absorbing 100% of damage dealt by the Winds."}
MultiLanguageSpellData['en'][359395] = {name = "Blood Link", additional_info = "Instant\n[q]While inside the Maw or Torghast, damaging an enemy establishes a Blood Link.\n\n Blood Link pulses every 3 sec, dealing 102858 Shadow damage and healing you for 100% of damage dealt. If your Blood Link would overheal you, it instead heals a nearby ally. Limit 1."}
MultiLanguageSpellData['en'][359396] = {name = "Chaos Bane", additional_info = "Instant\nApproximately 8 procs per minute\n[q]While inside the Maw or Torghast, your spells and abilities have a chance to drain a Soul Fragment from your target, granting you 605 Primary stat for 30 sec and stacking up to 15 times.\n\n When you reach 15 stacks, unleash Chaos Bane, dealing 90686 Shadow damage split between nearby enemies and granting you 18137 Primary stat for 15 sec.\n(500ms cooldown)"}
MultiLanguageSpellData['en'][359397] = {name = "Howling Blizzard", additional_info = nil}
MultiLanguageSpellData['en'][359398] = {name = "Starfall", additional_info = nil}
MultiLanguageSpellData['en'][359399] = {name = "Starfall", additional_info = "200 yd range\nInstant\n[q]Calls down waves of falling stars upon enemies within 40 yds, dealing [9 * (22.4% of Spell Power)] Astral damage over 8 sec. Multiple uses of this ability may overlap. [ Aetherial Kindling : Extends the duration of active Moonfires and Sunfires by 3 sec ]"}
MultiLanguageSpellData['en'][359400] = {name = "Spiked Balls", additional_info = "Instant\n[q]The Painsmith drops spiked balls that roll across the chamber floor, inflicting 400 Physical damage to players caught in their path and stunning them for 8 sec."}
MultiLanguageSpellData['en'][359401] = {name = "Genesis Crawler", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The Enlightened who have observed tarachnids believe that this variety may be some of the first beings to ever walk the land of Zereth Mortis.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359402] = {name = "Tarachnid Creeper", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"These tarachnids make their home in the darkest corners of Zereth Mortis, coming out only to hunt (or, sometimes, carry a rider around).\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359403] = {name = "Ineffable Skitterer", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"These tarachnids move with a purpose unknown to others, answering only to a higher calling. Whatever that may be, it appears to include routine assistance to mortals who need a ride. For now.\"\nProfession:\nProtoform Synthesis"}
MultiLanguageSpellData['en'][359407] = {name = "Wastewarped Deathwalker", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Raw swirling energy bound together into a cohesive form, it will only bend to the will of those strong enough to bind it.\"\nAchievement:\nShadowlands Keystone Master: Season Three\nCategory:\nDungeons"}
MultiLanguageSpellData['en'][359408] = {name = "Divine Kiss of Ohn'ahra", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount."}
MultiLanguageSpellData['en'][359409] = {name = "Iskaara Trader's Ottuk", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"There are no guarantees when you purchase an ottuk from Tattukiaka. At least they're cute.\"\nVendor:\nTattukiaka\nZone:\nThe Azure Span\nCost:\n1\n1"}
