MultiLanguageSpellData['en'][370525] = {name = "Potion of Chilled Clarity", additional_info = "2 sec cast\nReagents:\nAwakened Frost , Awakened Decay , Bubble Poppy (10), Draconic Vial (5)\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\n[q]This putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDiscovery:\nPotion Experimentation\nRequires:\nSpecialization: Alchemical Theory - Decayology\n\nToxic\n\n[q2]Use: Reduces the mana cost of all spells by 100% but also increases cast time by 40% for 9 seconds. (5 Min Cooldown)\n61"}
MultiLanguageSpellData['en'][370528] = {name = "Potion of Withering Vitality", additional_info = "2 sec cast\nReagents:\nAwakened Frost , Awakened Decay , Writhebark (10), Draconic Vial (5)\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\n[q]This putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDiscovery:\nPotion Experimentation\nRequires:\nSpecialization: Alchemical Theory - Decayology\n\nToxic\n\n[q2]Use: Consume this vile concoction to instantly heal yourself for 9156 , but suffer that same amount as Plague damage over 15 sec. (5 Min Cooldown)\n61"}
MultiLanguageSpellData['en'][370533] = {name = "Residual Neural Channeling Agent", additional_info = "2 sec cast\nReagents:\nAwakened Air , Awakened Earth , Saxifrage (10), Draconic Vial (5)\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\nDiscovery:\nPotion Experimentation\n\n\n[q2]Use: While dead, assault your enemy's consciousness with what remains of your own, dealing [ 391 * (9)] Nature damage over 18 sec to your target. Should you be revived, the remaining damage will be dealt instantly. Releasing your spirit will return your consciousness to you and cancel the effect.\n\nShares a cooldown with combat potions.\n61"}
MultiLanguageSpellData['en'][370536] = {name = "Delicate Suspension of Spores", additional_info = "2 sec cast\nReagents:\nAwakened Frost , Awakened Decay , Bubble Poppy (10), Draconic Vial (5)\nOptional Reagents:\nAlchemical Catalyst (#91) , Lesser Illustrious Insight (#92)\n[q]This putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDiscovery:\nPotion Experimentation\nRequires:\nSpecialization: Alchemical Theory - Decayology\n\n\n[q2]Use: Use upon a fallen ally within 10 yds to spread restorative spores nearby for 12 sec. These spores cling to allies and heal them for [ 332 * (3)] over 6 sec.\n\n Usable on yourself while dead. Shares a cooldown with combat potions. (5 Min Cooldown)\n61"}
