MultiLanguageSpellData['en'][382308] = {name = "Empowered Stomp", additional_info = "{2 sec cast} {12 sec cooldown}\n[q]Stuns all enemies within 8 yards, rendering them unable to move or attack for 3 sec.\n Inflicts 15 Arcane damage to enemies within 8 yards."}
MultiLanguageSpellData['en'][382309] = {name = "Ancestral Awakening", additional_info = "[q]When you heal with your Healing Wave, Healing Surge, or Riptide you have a 30% chance to summon an Ancestral spirit to aid you, instantly healing an injured friendly party or raid target within 40 yards for 15% of the amount healed. Critical strikes increase this chance to 60%."}
