MultiLanguageSpellData['en'][382312] = {name = "Refreshment", additional_info = "Instant\n[q]Restores ( 80357 / 5 * 20) health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 76 Primary Stat for 1 hour.\n\n Good fortune to you!"}
