MultiLanguageSpellData['en'][382321] = {name = "[q4]Ol' Smoky", additional_info = "5 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nObsidian Seared Alloy (4), Everburning Blasting Powder (8), Arclight Capacitor (2), Reinforced Machine Chassis , Spark (#247) (2)\nOptional Reagents:\nInfuse with Power (#111) , Customize Secondary Stats (#125) , Illustrious Insight (#93) , Add Embellishment (#226) , Spare Parts (#230)\nDrop:\nAssault of the Zaqali\nZone:\nAberrus, the Shadowed Crucible\nRecipe:\nPurchasable on the Auction House\n\n[q4]Ol' Smoky\nBinds when picked up\nRanged Gun\n406 - 754 Damage Speed 3.00\n(193.3 damage per second)\n+257 Agility\n+416 Stamina\n[q2]+ 239 Random Stat 1\n[q2]+ 239 Random Stat 2\nDurability 120 / 120\n58"}
MultiLanguageSpellData['en'][382322] = {name = "[q2]Primal Deconstruction Charge", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire , Handful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\n[q2]Primal Deconstruction Charge\n\n[q2]Use: Inflicts 531 Fire damage to enemies in a 8 yard radius. This explosion is powerful enough to cause moderate siege damage.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382323] = {name = "[q2]Grease Grenade", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Handful of Serevite Bolts (4), Everburning Blasting Powder (6)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\n\n[q2]Grease Grenade\n\n[q2]Use: Launch a concealed grenade toward the target location, dealing 837 Nature damage and coating the ground in a sticky substance for 4 sec that slows enemy units within by 75%. (5 Min Cooldown)\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382324] = {name = "[q3]Tinker: Breath of Neltharion", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire (3), Handful of Serevite Bolts (5), Everburning Blasting Powder (8), Greased-Up Gears (4), Reinforced Machine Chassis\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\n[q]Meticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nTreasure:\nCrumpled Schematic\nZone:\nNeltharus\n\n[q3]Tinker: Breath of Neltharion\nTinker Module\nUnique-Equipped: Breath of Neltharion (1)\nReveal a flamethrower to deal ( 517 * 13) Fire damage in a cone in front of you for 6 sec.\n58\n[q]\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\""}
MultiLanguageSpellData['en'][382325] = {name = "[q2]Projectile Propulsion Pinion", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrameless Lens , Greased-Up Gears (3), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nGather:\nDjaradin Cache\nZone:\nThe Waking Shores\n\n[q2]Projectile Propulsion Pinion\n\n[q2]Use: Permanently enchants a ranged weapon to grant 131 split between your highest and lowest secondary stats after you stand still for 3 sec.\n61"}
MultiLanguageSpellData['en'][382326] = {name = "[q2]High Intensity Thermal Scanner", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrameless Lens , Greased-Up Gears (3), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nFunction Over Form - Utility (20)\n\n[q2]High Intensity Thermal Scanner\n\n[q2]Use: Permanently enchants a ranged weapon to sometimes increase a secondary stat by 370 based upon the type of creature you are attacking.\n61"}
MultiLanguageSpellData['en'][382327] = {name = "Bundle of Fireworks", additional_info = "1.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire (3), Stonecrust Hide , Everburning Blasting Powder (2)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\n\nBinds when picked up\n[q]\"Contains an assortment of fireworks across many eras and from many cultures.\"\n[q2]<Right Click to Open>"}
MultiLanguageSpellData['en'][382328] = {name = "[q4]S.A.V.I.O.R.", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Order , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Greased-Up Gears (2), Arclight Capacitor\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nMechanical Mind (40)\n\n[q4]S.A.V.I.O.R.\nBinds when picked up\n\n[q2]Use: Place a friendly mechanical construct on the ground nearby which will offer moral support as your companions fall around you. It will resurrect all party or raid members within a reasonable distance after combat has ended. Cast time is reduced by quality.\n\n Does not work on players whose spirits have been released, are above level 70, or have angered the robot.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382329] = {name = "[q3]Khaz'gorite Fisherfriend", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nKhaz'gorite Ore (10), Greased-Up Gears (4), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nIllustrious Insight (#93) , Spare Parts (#230)\nDrop:\nImmaculate Sac of Swog Treasures\nVendor:\nThe Great Swog\nCost:\nGold Coin of the Isles\nRecipe:\nPurchasable on the Auction House\n\n[q3]Khaz'gorite Fisherfriend\nBinds when picked up\nFishing Tool\n[q2]+ 90 Perception\n[q2]Equip: +15 Dragon Isles Fishing Skill\nRequiresFishing\n(1)"}
MultiLanguageSpellData['en'][382330] = {name = "[q2]Creature Combustion Canister", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (6)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nProfession Trainer:\nDragon Isles Engineering (25)\nCost:\n1\n\n[q2]Creature Combustion Canister\n\n[q2]Use: Throw the canister, exploding the nearest meaty corpse into chunks of meat. Only usable outdoors.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382331] = {name = "[q2]D.U.C.K.O.Y.", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nContoured Fowlfeather (6), Resilient Leather , Handful of Serevite Bolts , Everburning Blasting Powder (2)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\n[q2]D.U.C.K.O.Y.\nBinds when picked up\n\n[q2]Use: Activate a robotic duckling that wanders around, annoying your enemies before self-destructing for 779 Fire damage split between all nearby enemies.\n\n Damage is increased for each enemy struck, up to 5 enemies.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382332] = {name = "[q3]Quack-E", additional_info = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nContoured Fowlfeather (60), Quack-E Quack Modulator , Malygite (2), Handful of Serevite Bolts (4), Shock-Spring Coil , Greased-Up Gears (2), Reinforced Machine Chassis\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 21\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 21\nCost:\n200\n\n[q3]Quack-E\nBinds when picked up\n[q2]Use: Teaches you how to summon and dismiss this companion.\n[q2]Right Click to summon and dismiss this companion.\n1 to 80 ( 80)"}
MultiLanguageSpellData['en'][382333] = {name = "[q3]Sticky Warp Grenade", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Handful of Serevite Bolts (6), Shock-Spring Coil (2), Everburning Blasting Powder (3)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\n[q3]Sticky Warp Grenade\n\n[q2]Use: Throw at a location, attaching itself to the surface or a nearby enemy. Detonates after 3 sec, swapping your position with itself and any attached enemy.\n\n Item quality affects the distance this can be thrown. Only usable outdoors.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382334] = {name = "[q3]Tinker: Alarm-O-Turret", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Ire (2), Shock-Spring Coil (3), Greased-Up Gears (3), Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\n[q]Meticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\n[q3]Tinker: Alarm-O-Turret\nTinker Module\nUnique-Equipped: Alarm-O-Turret (1)\nPlace a hidden Alarm-O-Turret on a nearby targeted location. If an enemy player enters its detection radius, it will alert you of their presence and attempt to defend the area for 30 sec or until destroyed.\n58\n[q]\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\""}
