MultiLanguageSpellData['en'][382343] = {name = "[q2]Gravitational Displacer", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPotion of Gusts , Handful of Serevite Bolts (2), Shock-Spring Coil , Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\n[q2]Gravitational Displacer\n\n[q2]Use: Throw the displacer and activate it after 2 sec, pulling all enemies within 10 yards to its location. Only usable outdoors.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382344] = {name = "[q3]Tinker: Grounded Circuitry", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (4), Greased-Up Gears (2), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nDothenos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\nVendor:\nUnatos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\n[q3]Tinker: Grounded Circuitry\nTinker Module\nUnique-Equipped: Grounded Circuitry (1)\nGuarantees the next slotted Tinker use to succeed. The cooldown of this effect is reduced at higher qualities.\n58\n[q]\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\""}
MultiLanguageSpellData['en'][382345] = {name = "Assorted Safety Fuses", additional_info = "1.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nWildercloth (3), Handful of Serevite Bolts (3), Shock-Spring Coil , Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nExplosives - EZ-Thro\n\n58\nCrafting Reagent\n[q]\"A critical component when creating Engineering bombs intended for people with careless hands. Can be bought and sold on the auction house.\""}
MultiLanguageSpellData['en'][382346] = {name = "[q2]Haphazardly Tethered Wires", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Earth (4), Handful of Serevite Bolts (3)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nProfession Trainer:\nDragon Isles Engineering (25)\nCost:\n1\n\n[q2]Haphazardly Tethered Wires\n58\nFinishing Crafting Reagent\n\n[q2]When crafting: You are 15% more likely to improve at Engineering, but Recipe Difficulty is increased by 30.\n[q]Usable with: Most Dragon Isles Engineering recipes."}
MultiLanguageSpellData['en'][382347] = {name = "Witherbolt", additional_info = "Instant\n[q]Infused with decay magic from a nearby totem, Trickclaw Mystic fires a withering bolt, inflicting 14 Nature damage and applying Withering ."}
MultiLanguageSpellData['en'][382348] = {name = "[q2]Overcharged Overclocker", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire (5), Handful of Serevite Bolts (2), Shock-Spring Coil (3)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nProfession Trainer:\nDragon Isles Engineering (40)\nCost:\n1\n50\n\n[q2]Overcharged Overclocker\n58\nFinishing Crafting Reagent\n\n[q2]When crafting: Increases your Resourcefulness by 55 and Ingenuity by 50.\n[q]Usable with: Most Dragon Isles Engineering recipes."}
MultiLanguageSpellData['en'][382349] = {name = "[q2]Critical Failure Prevention Unit", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nShock-Spring Coil (3), Arclight Capacitor , Reinforced Machine Chassis , Primal Deconstruction Charge (2)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nTinker Malfunction\nRequires:\nSpecialization: Function Over Form - Gears for Gear (20)\n\n[q2]Critical Failure Prevention Unit\n58\nOptional Crafting Reagent\n[q2]+20 Recipe Difficulty\n[q2]Provides the following property: Tinkers slotted into this device can no longer catastrophically malfunction.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382350] = {name = "[q2]Calibrated Safety Switch", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nShock-Spring Coil (2), Greased-Up Gears , Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nTinker Malfunction\nRequires:\nSpecialization: Function Over Form - Gears for Gear (20)\n\n[q2]Calibrated Safety Switch\n58\nOptional Crafting Reagent\n[q2]+20 Recipe Difficulty\n[q2]Provides the following property: Reduces the likelihood of this device's tinker malfunctioning by 15%. Does not stack with similar specialization bonuses.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382351] = {name = "[q3]Magazine of Healing Darts", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRefreshing Healing Potion (10), Everburning Blasting Powder (3), Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nFunction Over Form - Gears for Gear (10)\n\n[q3]Magazine of Healing Darts\n58\nOptional Crafting Reagent\n[q2]+35 Recipe Difficulty\n[q2]Provides the following property: When you heal you sometimes fire a Healing Dart. Also add Unique-Equipped: Embellished (2).\n[q]Usable with: Dragon Isles recipes for most unembellished Epic equipment."}
MultiLanguageSpellData['en'][382353] = {name = "[q2]I.W.I.N. Button Mk10", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts , Shock-Spring Coil , Arclight Capacitor , Primal Deconstruction Charge\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nExplosives (40)\n\n[q2]I.W.I.N. Button Mk10\nBinds when picked up\n\n[q2]Use: Press the button to call in an air strike at the designated location, dealing 5283 Fire damage to all enemies in the strike zone. Only usable outdoors.\n58\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382354] = {name = "[q3]Suspiciously Ticking Crate", additional_info = "2 sec cast 20 hrs cooldown\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire , Handful of Serevite Bolts (3), Shock-Spring Coil , Everburning Blasting Powder (10)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nExplosives - Short Fuse (30)\n\n[q3]Suspiciously Ticking Crate\nBinds when picked up\n58\n[q]\"Contains an assortment of dangerous bombs.\"\n[q2]<Right Click to Open>"}
MultiLanguageSpellData['en'][382355] = {name = "[q2]EZ-Thro Creature Combustion Canister", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (6), Assorted Safety Fuses\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nDiscovery:\nWhen crafting Creature Combustion Canister\nRequires:\nSpecialization: Explosives - EZ-Thro\n\n[q2]EZ-Thro Creature Combustion Canister\n\n[q2]Use: Throw the canister, exploding the nearest meaty corpse into chunks of meat. Only usable outdoors.\n58\n[q]\"So EZ that even non-Engineers can use it!\""}
MultiLanguageSpellData['en'][382356] = {name = "[q2]EZ-Thro Gravitational Displacer", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Potion of Gusts , Handful of Serevite Bolts (2), Shock-Spring Coil , Everburning Blasting Powder (4), Assorted Safety Fuses\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Gravitational Displacer\nRequires:\nSpecialization: Explosives - EZ-Thro\n\n[q2]EZ-Thro Gravitational Displacer\n\n[q2]Use: Throw the displacer and activate it after 2 sec, pulling all enemies within 10 yards to its location. Only usable outdoors.\n58\n[q]\"So EZ that even non-Engineers can use it!\""}
MultiLanguageSpellData['en'][382357] = {name = "[q2]EZ-Thro Primal Deconstruction Charge", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire , Handful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (4), Assorted Safety Fuses\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nDiscovery:\nWhen crafting Primal Deconstruction Charge\nRequires:\nSpecialization: Explosives - EZ-Thro\n\n[q2]EZ-Thro Primal Deconstruction Charge\n\n[q2]Use: Inflicts 496 Fire damage to enemies in a 8 yard radius. This explosion is powerful enough to cause moderate siege damage.\n58\n[q]\"So EZ that even non-Engineers can use it!\""}
MultiLanguageSpellData['en'][382358] = {name = "[q3]Suspiciously Silent Crate", additional_info = "2 sec cast 20 hrs cooldown\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire , Handful of Serevite Bolts (3), Shock-Spring Coil , Everburning Blasting Powder (10), Assorted Safety Fuses (2)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nExplosives - EZ-Thro (30)\n\n[q3]Suspiciously Silent Crate\nBinds when picked up\n58\n[q]\"Contains an assortment of Ez-Thro Bombs.\"\n[q2]<Right Click to Open>"}
MultiLanguageSpellData['en'][382359] = {name = "[q3]Tinker: Supercollide-O-Tron", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire (5), Awakened Order (3), Shock-Spring Coil (3), Greased-Up Gears (10), Arclight Capacitor (3), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\n[q]Meticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nSpecialization:\nMechanical Mind - Inventions (40)\n\n[q3]Tinker: Supercollide-O-Tron\nTinker Module\nUnique-Equipped: Supercollide-O-Tron (1)\nLock on to a distant enemy target, up to 12 to 60 yds away. After 1.5 sec, if your path remains unobstructed, you will charge toward them at the speed of sound. Both you and your target will be stunned for 1.5 sec upon collision.\n58\nRequiresDragon Isles Engineering\n(1)\n[q]\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\""}
MultiLanguageSpellData['en'][382361] = {name = "[q2]Razor-Sharp Gear", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nQueen's Ruby , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\n[q2]Razor-Sharp Gear\n58\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Critical Strike.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382362] = {name = "[q2]Rapidly Ticking Gear", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nVibrant Emerald , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\n[q2]Rapidly Ticking Gear\n58\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Haste.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382363] = {name = "[q2]Meticulously-Tuned Gear", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSundered Onyx , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\n[q2]Meticulously-Tuned Gear\n58\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Mastery.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382364] = {name = "[q2]One-Size-Fits-All Gear", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nMystic Sapphire , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\n[q2]One-Size-Fits-All Gear\n58\nOptional Crafting Reagent\n[q2]+25 Recipe Difficulty\n[q2]Provides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Versatility.\n[q]Usable with: Dragon Isles Engineering recipes for Epic goggles and bracers."}
MultiLanguageSpellData['en'][382365] = {name = "[q2]Completely Safe Rockets", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (2), Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nFunction Over Form - Utility\n\n[q2]Completely Safe Rockets\n\n[q2]Use: Throw in a seemingly endless supply of tiny rockets into your quiver. Your attacks have a chance to fire one of these rockets which explodes on impact to deal 1766 Fire damage in a small radius around the target.\n\n Lasts 60 min.\n58"}
MultiLanguageSpellData['en'][382366] = {name = "[q2]Endless Stack of Needles", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (2), Shock-Spring Coil , Greased-Up Gears\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nFunction Over Form - Utility (10)\n\n[q2]Endless Stack of Needles\n\n[q2]Use: Replace your traditional ammunition with sharp needles that cause your auto-attacks to also apply a bleed to the target which deals 424 Physical damage every 2 sec.\n\n Lasts 60 min.\n58"}
MultiLanguageSpellData['en'][382367] = {name = "[q3]Wyrmhole Generator: Dragon Isles", additional_info = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Order (3), Handful of Serevite Bolts (2), Shock-Spring Coil , Greased-Up Gears (2), Arclight Capacitor (3), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind\n\n[q3]Wyrmhole Generator: Dragon Isles\nBinds when used\nToy\n[q2]Use: Open a wormhole that allows the user to quickly travel to a random location in the Dragon Isles.\n\n Engineers that specialize into triangulation can learn to warp to specific locations. (30 Min Cooldown)\nRequiresDragon Isles Engineering\n(1)"}
MultiLanguageSpellData['en'][382368] = {name = "[q3]Centralized Precipitation Emitter", additional_info = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrosty Soul (3), Airy Soul (3), Elemental Harmony , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Arclight Capacitor (4), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind - Novelties (5)\n\n[q3]Centralized Precipitation Emitter\nBinds when used\nToy\n[q2]Use: Place down a Centralized Precipitation Emitter for up to 2 hrs that allows you to experience the fury of nature, by choice!\n\n A cloaking device attached to this machine ensures that only members of your party or raid can see the machine and its effects.\n\n Can only be used outside. (2 Hrs Cooldown)"}
MultiLanguageSpellData['en'][382369] = {name = "[q3]Environmental Emulator", additional_info = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFiery Soul (3), Earthen Soul (3), Elemental Harmony , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Arclight Capacitor (4), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind - Novelties (25)\n\n[q3]Environmental Emulator\nBinds when used\nToy\n[q2]Use: Place down an Environmental Emulator for up to 2 hrs that allows you to view the world from a different perspective.\n\n A cloaking device attached to this machine ensures that only members of your party or raid can see the machine and its effects.\n\n Can only be used outside. (2 Hrs Cooldown)"}
MultiLanguageSpellData['en'][382370] = {name = "[q3]Giggle Goggles", additional_info = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nNeltharite (2), Frameless Lens (2), Handful of Serevite Bolts (6), Shock-Spring Coil (3), Arclight Capacitor (2), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind - Novelties (20)\n\n[q3]Giggle Goggles\nBinds when used\nToy\n[q2]Use: Perceive the world as though it were ruled by gnolls. (1 Hour Cooldown)"}
