MultiLanguageSpellData['en'][393059] = {name = "Thousandbite Piranha", additional_info = "5 yd range\n3.2 sec cast\n[q]Thousandbite Piranha are an aggressive freshwater fish that will devour anything in sight!\n\n These freshwater swarms are found primarily in vast lakes and sprawling river systems across the Dragon Isles.\n\n They are especially active in areas such as The Ohn'ahran Plains and The Waking Shores."}
MultiLanguageSpellData['en'][393060] = {name = "Cerulean Spinefish", additional_info = "5 yd range\n3.2 sec cast\n[q]Cerulean Spinefish are a sturdy fish adorned with many sharp spines.\n\n These saltwater schools can be found primarily in the ocean and other bodies of water connected to it.\n\n They are especially active in areas such as the river openings around The Waking Shores."}
MultiLanguageSpellData['en'][393061] = {name = "Aileron Seamoth", additional_info = "5 yd range\n3.2 sec cast\n[q]Aileron Seamoth glide across the ocean floor and jet upwards when they suspect a tasty treat!\n\n These saltwater schools can be found primarily in the ocean and other bodies of water connected to it.\n\n They are especially active in areas such as Iskaara in The Azure Span."}
MultiLanguageSpellData['en'][393062] = {name = "Temporal Dragonhead", additional_info = "5 yd range\n3.2 sec cast\n[q]Temporal Dragonhead are a peculiar fish whose scales seem to displace forwards and backwards every few seconds. Keep your fingers away from their sharp snout!\n\n These freshwater schools can be found primarily in the vast lakes and sprawling river systems around the Dragon Isles.\n\n They are especially active in areas such as the Uktulut Backwater in The Waking Shores."}
MultiLanguageSpellData['en'][393063] = {name = "Scalebelly Mackerel", additional_info = "5 yd range\n3.2 sec cast\n[q]Scalebelly Mackerel are an incredibly common fish in the Dragon Isles. They are easily caught in all bodies of water.\n\n Tossing unused Scalebelly Mackerel back into the water is a routine exercise done by even the most experienced Anglers."}
MultiLanguageSpellData['en'][393064] = {name = "Islefin Dorado", additional_info = "5 yd range\n3.2 sec cast\n[q]Islefin Dorado are an elusive fish whose fin is said to resemble the Dragon isles.\n\nThey are found in all bodies of water around the isles."}
MultiLanguageSpellData['en'][393065] = {name = "Shimmering Treasure", additional_info = "5 yd range\n3.2 sec cast\n[q]Shimmering Treasure can appear in all bodies of water across the Dragon Isles. These pools contain untold treasures and are what every angler hopes to stumble upon.\n\nFishing in these pools significantly increases your chance for rare treasures."}
MultiLanguageSpellData['en'][393066] = {name = "Rimefin Tuna", additional_info = "5 yd range\n3.2 sec cast\n[q]Rimefin Tuna are a large, fatty fish coated in a thin layer of protective ice. The thick layer of fat protects their vital organs in below freezing temperatures.\n\n You can find these pools in especially frosty climates around the Dragon Isles.\n\n The Iskaara Tuskarr are experts in catching these kinds of special fish."}
MultiLanguageSpellData['en'][393067] = {name = "Magma Thresherl", additional_info = "5 yd range\n3.2 sec cast\n[q]Magma Threshers are a muscular fish with a hardened outer shell consisting of various minerals.\n\n You can find these pools in especially hot climates around the Dragon Isles.\n\n The Iskaara Tuskarr are experts in catching these kinds of special fish."}
